mapper.select:
SELECT id, user_id, provider, api_key, base_url, enabled, created_at, updated_at
FROM api_key
WHERE id = #{id}

SELECT id, user_id, provider, api_key, base_url, enabled, created_at, updated_at
FROM api_key
WHERE user_id = #{userId}
  AND provider = #{provider}
  AND enabled = 1
LIMIT 1
